import {compareMaterialStocks} from './tank-stock-comparison.js';
import {esc,fmt} from './tank-visuals.js';
import {stockLabel} from './tank-stock-config.js';
const mass=n=>n===null?'待補資料':fmt(n,2)+' kg';
export function stockPurchaseMarkup(r,{openKeys}={}){
  const c=compareMaterialStocks(r);if(!c.groups.length)return '';
  const opens=new Set(openKeys??[c.groups[0].group.selectionKey]);
  return `<section class="stock-buy"><header><div><span class="workbench-eyebrow">PLATE PURCHASE</span><h3>每組材料，挑一種原板</h3><p>先比較省料，再決定怎麼買。${c.partial?'目前只比較已確認毛坯，待補項不算零料。':''}</p></div><button type="button" data-stock-best="all" ${!c.changes.length?'disabled':''}>${c.changes.length?(c.groups.every(x=>x.best)?'套用各組省料建議':'套用可比較組的建議'):c.groups.some(x=>!x.best)?'尚有材料組需調整':'目前各組已是省料選擇'}</button></header><div class="stock-buy-total"><div><span>目前已排原板</span><strong>${mass(c.currentWeight)}</strong></div><div><span>各組建議合計</span><strong>${mass(c.recommendedWeight)}</strong></div><div><span>${c.savingWeight===null?'資料待補':'比目前少買'}</span><strong>${c.savingWeight===null?'—':mass(c.savingWeight)}</strong></div></div>${c.groups.map(({group:g,options,best,current,savingWeight,automatic,quoted})=>{
    const key=encodeURIComponent(g.selectionKey),currentLabel=quoted?'已套用報價料源':stockLabel({stockWidth:g.width,stockLength:g.length}),same=best?.selected;
    return `<details class="stock-buy-group" data-stock-buy-key="${key}" ${opens.has(g.selectionKey)?'open':''}><summary><span><strong>${esc(g.material)} <b>t${fmt(g.thickness)} mm</b></strong><small>目前 ${esc(currentLabel)} · ${g.sheetCount} 張${g.stockId==='inherit'?' · 沿用預設':''}${g.unplaced?' · 有毛坯未排入':''}</small></span><span class="stock-buy-recommend">${best?(same?'目前已省料':'建議 '+esc(best.label)):'待調整毛坯'}${savingWeight>1e-6?`<small>可少買 ${mass(savingWeight)}</small>`:''}<i aria-hidden="true">⌄</i></span></summary><div class="stock-buy-options">${options.map(o=>`<button type="button" data-stock-choose="${key}" data-stock-size="${o.id}" aria-pressed="${o.selected}" ${!o.feasible?'disabled':''} aria-label="${esc(g.material)} t${fmt(g.thickness)} 選用 ${esc(o.label)}"><span class="stock-buy-option-head"><strong>${esc(o.label)}</strong><small>${o.selected?'✓ 使用中':o===best?'省料建議':'比較'}</small></span><span class="stock-buy-size">${fmt(o.stockLength)} × ${fmt(o.stockWidth)} mm</span>${o.feasible?`<span class="stock-buy-quantity">${o.sheetCount} <small>張原板</small></span><span class="stock-buy-metrics"><span>採購<strong>${mass(o.weight)}</strong></span><span>餘料／損耗<strong>${mass(o.offcutWeight)}</strong></span></span><span class="stock-buy-foot">毛坯利用 ${fmt(o.utilization,1)}%${o.largestFree?'<br>最大餘板約 '+fmt(o.largestFree.w,0)+' × '+fmt(o.largestFree.h,0)+' mm':''}${automatic?'<br>全槽已知焊長 '+fmt(o.knownWeldLength/1000,2)+' m':''}</span>`:`<span class="stock-buy-failed">${esc(o.reason)}</span>`}</button>`).join('')}</div><div class="stock-buy-explain"><p>${best?`同材同厚按${g.density===null?'板面積':'採購重量'}比較${options.some(o=>o!==best&&o.feasible&&Math.abs(o.purchasedArea-best.purchasedArea)<1e-4)?'；同採購量優先少張數、短焊縫':''}。${automatic?'換板會重算分片及已知焊長。':''}`:'沒有可完整排入本組毛坯的板型，請先調整分片／尺寸。'}${best&&best.utilization<25?'本組整張利用率偏低，可另詢同材同厚的裁切料／餘板報價；目前仍按整張計。':''}${quoted?'目前使用報價採購排法；此處只作單一整張板參考。':!current?.feasible?'目前配置未完成，不計節省差額。':''}</p><div class="stock-buy-actions">${best&&!same?`<button type="button" data-stock-best="${key}">此組改用 ${esc(best.label)} →</button>`:''}${g.stockId!=='inherit'?`<button type="button" data-stock-inherit="${key}" class="stock-buy-inherit">恢復沿用預設</button>`:''}</div></div></details>`;
  }).join('')}<p class="tank-note">省料依目前矩形包絡排料比較，每組先比單一板型，未混搭同組不同尺寸，不保證最佳套排。餘料／損耗含刀縫及外形廢料；最大餘板為本次排法的矩形餘板，未折抵採購。未計單價、裁切、焊接及運費，不能當作最低金額。</p></section>`;
}
